import numpy as np


def q097(p, q):
    p, q = (np.asarray(p, float), np.asarray(q, float))
    mask = p > 0
    entropy = -np.sum(p[mask] * np.log(p[mask]))
    cross = (
        np.inf
        if np.any(q[mask] == 0)
        else -np.sum(p[mask] * np.log(q[mask]))
    )
    return (float(entropy), float(cross))
